export function validateOrdinaryState(v,sid){if(!exact(v,stateKeys)||v.schema_version!=='human-ordinary-runtime/1'||!['ready','blocked','terminal'].includes(v.status)||typeof v.reason_code!=='string'||!Number.isSafeInteger(v.run_control_version)||v.run_control_version<1||!Number.isSafeInteger(v.master_control_version)||v.master_control_version<1||!['prepared','opening_pending','started','closing_pending','terminal','cancelled','uncertain'].includes(v.phase)||typeof v.current_step_key!=='string'||!Array.isArray(v.commands))fail('Proiezione ordinaria non qualificata.');const s=sourceDTO(v.source,sid);v.commands.forEach(commandDTO);if(v.status!=='ready'&&v.commands.length)fail('Comandi inattesi in uno stato sospeso.');if(v.terminal!==null)terminalDTO(v.terminal,s);if(v.reward!==null){if(v.terminal===null)fail('Premio senza ricevuta terminale.');rewardDTO(v.reward,s,v.terminal);}return copy(v);}
