function notice(root,busy,message){root.setAttribute('aria-busy',String(busy));const n=node('p',busy?'Operazione in corso: il testo e la stessa richiesta sono conservati.':message);n.setAttribute('role','status');n.setAttribute('aria-live','polite');root.append(n);}
