function userMessage(error,fallback='Operazione non confermata. Testo e richiesta sono conservati: rileggi lo stato.'){const value=String(error?.message||'');return !value||value.length>240||/\b[A-Z][A-Z0-9_]{5,}\b|[0-9a-fA-F]{8}-[0-9a-fA-F-]{27,}|[0-9a-fA-F]{32,}/.test(value)?fallback:value;}
function normalTransport({client,identity,isCurrent=()=>true}){const actor=identity();if(!UUID.test(actor)||!client?.auth?.getUser||!client.rpc)fail('Accesso normale richiesto.');let disposed=false,generation=0;const current=()=>!disposed&&isCurrent()&&identity()===actor;const snapshot=()=>generation;const check=t=>{if(!current()||t!==generation)fail('Contesto cambiato: testo e richieste sono conservati.');};async function call(name,params){const t=snapshot();check(t);const a=await client.auth.getUser();check(t);if(a.error||a.data?.user?.id!==actor)fail('Accesso non confermato.');const r=await client.rpc(name,params);check(t);const after=await client.auth.getUser();check(t);if(after.error||after.data?.user?.id!==actor)fail('Accesso cambiato: recupera la stessa richiesta.');if(r.error)throw r.error;return r.data;}return{actor,current,call,invalidate(){generation++;},dispose(){disposed=true;generation++;}};}
