export function mountHumanOrdinaryMaster(root,{client,identity,isCurrent=()=>true,storage=globalThis.localStorage,api,onScene=()=>{},onBack=()=>{}}={}){let view=null,busy=false,message='',sid=null,d100=null,guide='',support='';const runtime=createHumanOrdinaryRuntime({client,identity,isCurrent:()=>root.isConnected&&isCurrent(),storage,onStatus:s=>{busy=s.busy;message=s.message;}});async function work(fn){if(busy)return;busy=true;draw();try{await fn();message='Stato confermato dal server.';}catch(e){message=userMessage(e);}finally{busy=false;if(root.isConnected&&isCurrent())draw();}}async function read(){view=await runtime.read();return view;}function draw(){if(!view)return;root.replaceChildren();notice(root,busy,message);root.append(node('h3','Conduzione umana'),node('p',phaseLabel(view.phase)),node('p',reasonLabel(view.reason_code)),action('Torna alla puntata',onBack,busy),action('Rileggi la scena',()=>work(read),busy));const j=runtime.journal();if(j.pending){root.append(node('p','Richiesta conservata. La lettura non invia comandi.'),action('Rileggi la stessa richiesta',()=>work(async()=>{await runtime.recover();await read();}),busy),action('Ripeti la stessa richiesta',()=>work(async()=>{await runtime.send(j.pending.operation,j.pending.params,{replay:true});await read();}),busy));return;}const publication=view.commands.find(x=>['fato','terminal','round'].includes(x.operation));if(publication){const area=node('textarea');area.setAttribute('aria-label','Fato unico della scena');area.value=j.body;area.maxLength=5000;area.disabled=busy;area.oninput=()=>runtime.setBody(area.value);root.append(area,action(publication.operation==='terminal'?'Pubblica conclusione e verifica premi':'Pubblica Fato unico',()=>work(async()=>{const p=publication.operation==='round'?{p_session:sid,p_window:publication.window_id,p_body:runtime.journal().body.trim(),p_expected_revision:publication.preparation_revision,p_request:crypto.randomUUID()}:{p_session:sid,p_event:publication.event_id,p_body:runtime.journal().body.trim(),p_request:crypto.randomUUID()};await runtime.send(publication.operation,p);await read();}),busy));}for(const c of view.commands.filter(x=>x.operation==='phase'))root.append(action(c.action==='open_encounter'?'Apri combattimento':c.action==='prepare_terminal'?'Concludi puntata':c.decision_key==='combat.peaceful'?'Concludi lo scontro pacificamente':'Prosegui la scena',()=>work(async()=>{await runtime.send('phase',{p_session:sid,p_expected_version:view.run_control_version,p_action:c.action,p_decision_key:c.decision_key,p_request:crypto.randomUUID()});await read();}),busy));for(const c of view.commands.filter(x=>x.operation==='consume'))root.append(action('Applica il tiro d100 confermato',()=>work(async()=>{await runtime.send('consume',{p_session:sid,p_receipt:c.receipt_id,p_source_sha256:c.source_sha256});await read();}),busy));if(api&&view.status==='ready'&&view.phase==='started'){root.append(action('Guida e supporto d100',()=>work(async()=>{d100=await api.d100Scope(sid);if(d100.source_sha256!==view.source.source_sha256||d100.run_control_version!==view.run_control_version)fail('Fase d100 cambiata.');guide=d100.assignment.guide_character_id||'';support=d100.assignment.support_character_id||'';}),busy));const pending=api.d100Journal(sid);if(pending&&!pending.receipt)root.append(action('Recupera stesso binding d100',()=>work(async()=>{await api.d100Recover(sid);await read();}),busy),action('Ripeti stesso binding d100',()=>work(async()=>{await api.d100Bind(sid,pending.params,{replay:true,scope:api.d100ScopeMeta(sid,pending.params.p_request)?.scope});await read();}),busy));else if(d100?.can_bind){for(const kind of ['guide','support']){if(kind==='support'&&!d100.support_required)continue;const select=node('select');select.setAttribute('aria-label',kind==='guide'?'Guida d100':'Supporto d100');const none=node('option','Scegli…');none.value='';select.append(none);for(const p of d100.roster){const o=node('option',p.display_name);o.value=p.character_id;select.append(o);}select.value=kind==='guide'?guide:support;select.disabled=busy;select.onchange=()=>{if(kind==='guide')guide=select.value;else support=select.value;};root.append(select);}root.append(action('Conferma guida e supporto',()=>work(async()=>{const p=api.d100ParamsForScope(d100,guide,d100.support_required?support:null,crypto.randomUUID());await api.d100Bind(sid,p,{scope:d100});await read();}),busy));}}if(view.phase==='started'&&view.status==='ready')root.append(action('Apri scena e Regia',()=>work(()=>onScene({schema_version:'human-ordinary-scene-link/1',session:sid,episode:view.source.quest_episode_id,location:view.source.location_id,execution_context:view.source.execution_context})),busy));if(view.reward)root.append(node('p',view.reward.schema_version==='quest-arc-reward-deferred/2'?'Conclusione pubblicata. Premio ancora da verificare.':view.reward.effect_mode==='simulation'?'Premio simulato: nessuna progressione reale modificata.':'Premio confermato dal registro del server.'));}return{async open(id){sid=id;view=await runtime.open(id);draw();},dispose(){runtime.dispose();},read:()=>work(read)};}

function ordinaryParticipantDTO(v,episode){const keys=['schema_version','quest_episode_id','quest_arc_id','source_sha256','release_sha256','execution_context','effect_mode','location_id','participant','award'];if(!exact(v,keys)||v.schema_version!=='human-ordinary-participant/1'||v.quest_episode_id!==episode||!UUID.test(v.quest_arc_id)||!SHA.test(v.source_sha256)||!SHA.test(v.release_sha256)||!['public_real','staff_simulation'].includes(v.execution_context)||v.effect_mode!==(v.execution_context==='public_real'?'real':'simulation')||v.location_id!==null&&!UUID.test(v.location_id))fail('La puntata assegnata non è compatibile.');const p=v.participant;if(!exact(p,['schema_version','quest_episode_id','character_id','phase','enrollment_open','enrollment_state','ready','enrollment_control_version','actions','present_now','native_session_id','terminal'])||p.schema_version!=='quest-episode-participant-state/1'||p.quest_episode_id!==episode||!UUID.test(p.character_id)||!['enrollment_open','prepared','opening_pending','started','closing_pending','terminal','uncertain','unavailable'].includes(p.phase)||typeof p.enrollment_open!=='boolean'||typeof p.ready!=='boolean'||![null,'joined','withdrawn'].includes(p.enrollment_state)||p.enrollment_control_version!==null&&!positive(p.enrollment_control_version)||p.present_now!==null&&typeof p.present_now!=='boolean'||!exact(p.actions,['join','withdraw','ready'])||Object.values(p.actions).some(x=>typeof x!=='boolean')||p.native_session_id!==null&&!UUID.test(p.native_session_id))fail('Iscrizione non compatibile.');if(p.phase==='terminal'){const t=p.terminal;if(!exact(t,['schema_version','quest_episode_id','native_terminal_receipt_id','outcome','reward_state','next_episode_eligible'])||t.schema_version!=='quest-episode-terminal-public/1'||t.quest_episode_id!==episode||!UUID.test(t.native_terminal_receipt_id)||!['success','failure'].includes(t.outcome)||t.reward_state!=='pending_staff'||t.next_episode_eligible!==false)fail('Conclusione non confermata.');}else if(p.terminal!==null)fail('Conclusione inattesa.');if(v.award!==null){const a=v.award;if(!exact(a,['schema_version','award_id','decision_id','arc_id','character_id','effect_mode','computed_xp','effective_xp','ryo','items'])||a.schema_version!=='quest-recipient-reward/2'||!UUID.test(a.award_id)||!UUID.test(a.decision_id)||a.arc_id!==v.quest_arc_id||a.character_id!==p.character_id||a.effect_mode!==v.effect_mode||a.computed_xp!==30||a.effective_xp!==(v.effect_mode==='real'?30:0)||a.ryo!==0||!Array.isArray(a.items)||a.items.length||p.phase!=='terminal')fail('Premio non confermato dal server.');}return copy(v);}
export function mountHumanOrdinaryParticipant(root,{client,identity,isCurrent=()=>true,storage=globalThis.localStorage,onScene=()=>{}}){if(!root?.isConnected)fail('Spazio Quest non disponibile.');const t=normalTransport({client,identity,isCurrent}),api=createQuestRuntimeApi(client,{identity,isCurrent:()=>t.current(),storage});let episode=null,view=null,busy=false,message='';async function read(){const next=ordinaryParticipantDTO(await t.call('mission_factory_quest_human_ordinary_participant_state_v1',{p_episode:episode}),episode);if(view&&view.source_sha256!==next.source_sha256)fail('Fonte della quest cambiata: nessuna scelta inviata.');view=next;return copy(next);}async function send(operation,{replay=false}={}){await read();const j=api.journal(episode);if(replay){if(j.pending?.operation!=='enrollment')fail('Nessuna richiesta di iscrizione conservata.');return api.send(episode,'enrollment',j.pending.params,{replay:true});}if(j.pending)fail('Rileggi la richiesta originale.');const p=view.participant;if(!p.actions[operation])fail('Scelta non offerta dal server.');return api.send(episode,'enrollment',{p_episode:episode,p_operation:operation,p_ready:operation==='ready'?!p.ready:null,p_expected_version:operation==='join'?null:p.enrollment_control_version,p_request:crypto.randomUUID()});}async function work(fn){if(busy)return;busy=true;draw();try{await fn();await read();message='Stato aggiornato.';}catch(e){message=userMessage(e);}finally{busy=false;if(t.current())draw();}}function draw(){if(!t.current()||!view)return;root.replaceChildren();notice(root,busy,message);root.append(node('h3','La tua quest'),node('p',phaseLabel(view.participant.phase)),action('Aggiorna stato',()=>work(read),busy));const j=api.journal(episode);if(j.pending){root.append(node('p','La richiesta originale è conservata.'),action('Rileggi la stessa richiesta',()=>work(()=>api.recover(episode)),busy),action('Ripeti la stessa richiesta',()=>work(()=>send(null,{replay:true})),busy));return;}for(const [op,label] of [['join','Partecipa'],['withdraw','Ritirati'],['ready',view.participant.ready?'Non sono pronto':'Sono pronto']])if(view.participant.actions[op])root.append(action(label,()=>work(()=>send(op)),busy));if(view.participant.native_session_id&&view.location_id)root.append(action('Vai alla scena',()=>onScene({schema_version:'human-ordinary-scene-link/1',session:view.participant.native_session_id,episode:view.quest_episode_id,location:view.location_id,execution_context:view.execution_context}),busy));if(view.award)root.append(node('p',view.effect_mode==='simulation'?'Prova conclusa: nessun premio reale assegnato.':'Premio assegnato dal server: 30 punti esperienza.'));else if(view.participant.phase==='terminal')root.append(node('p','Conclusione confermata. Il premio viene mostrato soltanto dopo la ricevuta del server.'));}return{async open(id){if(busy||!UUID.test(id))fail('Puntata non valida.');t.invalidate();episode=id;view=null;await read();draw();},read:()=>work(read),dispose(){t.dispose();api.dispose();}};}

const authoringOps={create:{rpc:'mission_factory_quest_human_ordinary_create_v1',keys:['p_lineage','p_expected_version','p_document','p_roster','p_request']},import:{rpc:'mission_factory_quest_human_ordinary_import_v1',keys:['p_native_draft','p_native_version','p_human_variant','p_roster','p_lineage','p_expected_version','p_request']},publish:{rpc:'mission_factory_quest_human_ordinary_publish_v1',keys:['p_draft','p_expected_version','p_preview_seal','p_request','p_visibility','p_scheduled_at']},canonical:{rpc:'mission_factory_npc_certify_existing_combat_v1',keys:['p_template','p_narrative_version','p_expected_template_control','p_request']}};
function authorParams(op,p){if(!authoringOps[op]||!exact(p,authoringOps[op].keys)||!UUID.test(p.p_request))fail('Richiesta di authoring incompatibile.');if(['create','import'].includes(op)&&(!UUID.test(p.p_lineage)||!Number.isSafeInteger(p.p_expected_version)||p.p_expected_version<0||!Array.isArray(p.p_roster)||p.p_roster.length<1||p.p_roster.length>4||new Set(p.p_roster).size!==p.p_roster.length||p.p_roster.some(x=>!UUID.test(x))))fail('Trama o partecipanti non compatibili.');if(op==='create'&&(!p.p_document||p.p_document.schema_version!=='mission-factory-draft/3'||p.p_document.content_kind!=='quest_dual')||op==='import'&&(!UUID.test(p.p_native_draft)||!positive(p.p_native_version)||!p.p_human_variant||typeof p.p_human_variant!=='object'||Array.isArray(p.p_human_variant))||op==='publish'&&(!UUID.test(p.p_draft)||!positive(p.p_expected_version)||!SHA.test(p.p_preview_seal)||p.p_visibility!=='open'||p.p_scheduled_at!==null)||op==='canonical'&&(!UUID.test(p.p_template)||!UUID.test(p.p_narrative_version)||!positive(p.p_expected_template_control)))fail('Contenuto non compatibile.');return copy(p);}
function authorReceipt(op,v,p){if(['create','import'].includes(op)){if(!exact(v,['schema_version','request_key','lineage_id','version','draft_id','roster_assignment_id','source_sha256','human_document_sha256','catalog_sha256'])||v.schema_version!=='quest-dual-human-create/3'||v.request_key!==p.p_request||v.lineage_id!==p.p_lineage||v.version!==p.p_expected_version+1||!UUID.test(v.draft_id)||!UUID.test(v.roster_assignment_id)||!['source_sha256','human_document_sha256','catalog_sha256'].every(k=>SHA.test(v[k])))fail('Salvataggio Human non confermato.');}else if(op==='publish'){if(!exact(v,['schema_version','request_key','draft_id','content_kind','quest_kind','state','visibility','scheduled_at','mission_id','quest_arc_id','quest_episode_id','source_sha256','config_version','activation_id'])||v.schema_version!=='quest-human-publish-receipt/3'||v.request_key!==p.p_request||v.draft_id!==p.p_draft||v.content_kind!=='quest_human'||!['one_shot','trama'].includes(v.quest_kind)||!['staff','open'].includes(v.state)||v.visibility!==v.state||v.scheduled_at!==null||v.mission_id!==null||!UUID.test(v.quest_arc_id)||!UUID.test(v.quest_episode_id)||!SHA.test(v.source_sha256)||v.config_version!==null||v.activation_id!==null)fail('Pubblicazione Human non confermata.');}else{if(!exact(v,['schema_version','request_key','template_id','narrative_version_id','mechanical_binding_id','npc_version_id','bundle_sha256','pair_request_key','status','reference'])||v.schema_version!=='human-existing-canonical-npc/1'||v.request_key!==p.p_request||v.template_id!==p.p_template||v.narrative_version_id!==p.p_narrative_version||!UUID.test(v.mechanical_binding_id)||!UUID.test(v.npc_version_id)||!SHA.test(v.bundle_sha256)||!UUID.test(v.pair_request_key)||v.status!=='certified'||!exact(v.reference,['schema_version','npc_id','npc_version_id','bundle_sha256','narrative_version_id','mechanical_version_id','mechanical_binding_id','combat'])||v.reference.schema_version!=='mission-factory-npc-reference/1'||v.reference.narrative_version_id!==v.narrative_version_id||v.reference.mechanical_binding_id!==v.mechanical_binding_id||!UUID.test(v.reference.mechanical_version_id)||v.reference.npc_id!==v.template_id||v.reference.npc_version_id!==v.npc_version_id||v.reference.bundle_sha256!==v.bundle_sha256||v.reference.combat!==true)fail('Certificazione PNG non confermata.');}return copy(v);}
export function createHumanOrdinaryAuthoring({client,identity,isCurrent=()=>true,workspace,storage=globalThis.localStorage,onStatus=()=>{}}){if(!UUID.test(workspace))fail('Workspace authoring non valido.');const t=normalTransport({client,identity,isCurrent}),key=`quest-human-ordinary-authoring/1/${t.actor}/${workspace}`;let busy=false;function journal(){let j;try{j=JSON.parse(storage.getItem(key)||'null');}catch{fail('Registro authoring non leggibile: nessun invio.');}if(j===null)return{schema_version:'human-ordinary-authoring-journal/1',actor:t.actor,workspace,pending:null,history:[],draft:null};if(!exact(j,['schema_version','actor','workspace','pending','history','draft'])||j.schema_version!=='human-ordinary-authoring-journal/1'||j.actor!==t.actor||j.workspace!==workspace||!Array.isArray(j.history))fail('Recupero authoring incompatibile.');if(j.pending){if(!exact(j.pending,['operation','params']))fail('Richiesta authoring incompatibile.');authorParams(j.pending.operation,j.pending.params);}for(const h of j.history){if(!exact(h,['operation','params','receipt']))fail('Storico authoring incompatibile.');authorReceipt(h.operation,h.receipt,authorParams(h.operation,h.params));}return j;}function store(j){if(!t.current())fail('Contesto cambiato: authoring conservato.');const raw=JSON.stringify(j);storage.setItem(key,raw);if(storage.getItem(key)!==raw)fail('Richiesta non conservata: nessun invio.');}function confirm(original,v){const j=journal();if(JSON.stringify(j.pending)!==JSON.stringify(original))fail('Richiesta originale cambiata: conserva l’esito.');const receipt=authorReceipt(original.operation,v,original.params);j.history.push({...copy(original),receipt});j.pending=null;store(j);return receipt;}async function exclusive(fn){if(busy)fail('Operazione già in corso.');busy=true;onStatus({busy:true,message:'Verifica in corso. Le modifiche sono conservate.'});try{return await fn();}finally{busy=false;if(t.current())onStatus({busy:false,pending:!!journal().pending,message:journal().pending?'La richiesta è conservata. Rileggi il suo esito.':'Pronto.'});}}async function send(op,p,{replay=false}={}){return exclusive(async()=>{p=authorParams(op,p);let j=journal();if(replay){if(j.pending?.operation!==op||JSON.stringify(j.pending.params)!==JSON.stringify(p))fail('La richiesta originale è diversa.');}else{if(j.pending)fail('Rileggi prima la richiesta originale.');j.pending={operation:op,params:p};store(j);}const original=copy(j.pending);const v=await t.call(authoringOps[op].rpc,p);return confirm(original,v);});}async function recover(){return exclusive(async()=>{const pending=journal().pending;if(!pending)return{state:'none'};const {operation:op,params:p}=pending;const value=await t.call(op==='canonical'?'mission_factory_npc_certify_existing_combat_receipt_v1':'mission_factory_quest_human_ordinary_authoring_receipt_v1',op==='canonical'?{p_template:p.p_template,p_narrative_version:p.p_narrative_version,p_request:p.p_request}:{p_request:p.p_request,p_operation:op});const keys=op==='canonical'?['schema_version','request_key','state','receipt']:['schema_version','request_key','operation','state','receipt'];if(!exact(value,keys)||value.schema_version!==(op==='canonical'?'human-existing-canonical-npc-receipt/1':'human-ordinary-authoring-receipt/1')||value.request_key!==p.p_request||op!=='canonical'&&value.operation!==op||!['not_found','committed'].includes(value.state)||value.state==='not_found'&&value.receipt!==null)fail('Recupero non confermato: richiesta conservata.');if(value.state==='committed')return{state:'committed',receipt:confirm(pending,value.receipt)};return{state:'not_found',retry_explicit:true};});}return{journal:()=>copy(journal()),setDraft(value){const j=journal();j.draft=copy(value);store(j);},send,recover,replay(){const p=journal().pending;if(!p)fail('Nessuna richiesta conservata.');return send(p.operation,p.params,{replay:true});},async preview(draft,version){if(!UUID.test(draft)||!positive(version))fail('Bozza non valida.');const v=await t.call('mission_factory_quest_human_ordinary_preview_v1',{p_draft:draft,p_expected_version:version});if(!exact(v,['schema_version','draft_id','draft_version','content_kind','quest_kind','preview_seal','validation_mode','required_variants','validated_variants','errors'])||v.schema_version!=='quest-human-preview/3'||v.draft_id!==draft||v.draft_version!==version||v.content_kind!=='quest_human'||v.validation_mode!=='human_only'||JSON.stringify(v.required_variants)!=='["human"]'||!Array.isArray(v.validated_variants)||!['[]','[\"human\"]'].includes(JSON.stringify(v.validated_variants))||!Array.isArray(v.errors)||v.preview_seal!==null&&(!SHA.test(v.preview_seal)||v.errors.length>0||JSON.stringify(v.validated_variants)!=='[\"human\"]'))fail('Anteprima Human non compatibile.');return copy(v);},dispose(){t.dispose();}};}

// LAND adoption point: the caller supplies an existing connected inline host and normal navigation callbacks.
// This creates no overlay, app shell replacement, role mutation, timer, provider call or gameplay retry.
export function mountHumanOrdinaryWorkspace(root,{client,identity,isCurrent=()=>true,storage=globalThis.localStorage,asParticipant=false,onScene=()=>{},onPrepared=()=>{},onBackToScene=()=>{}}){if(!root?.isConnected)fail('Workspace LAND non disponibile.');const section=node('section');section.className='h33-workspace';section.setAttribute('aria-label','Missioni e Quest con Master');const header=node('header');header.className='h33-head';header.append(node('h2','La tua avventura'),action('Torna alla scena',()=>{section.hidden=true;onBackToScene();}));const frame=node('section');frame.className='h33-ordinary-frame';section.append(header,frame);root.append(section);let closed=false;const live=()=>!closed&&section.isConnected&&isCurrent();const widget=asParticipant?mountHumanOrdinaryParticipant(frame,{client,identity,isCurrent:live,storage,onScene}):mountHumanOrdinaryEpisode(frame,{client,identity,isCurrent:live,storage,onScene,onPrepared});return{async open(episode){if(!live())fail('Contesto LAND cambiato.');section.hidden=false;await widget.open(episode);},show(){if(live())section.hidden=false;},hide(){section.hidden=true;},dispose(){closed=true;widget.dispose();section.hidden=true;}};}


export function validateHumanQuestRoute(v,episode){if(!UUID.test(episode)||!exact(v,['schema_version','quest_episode_id','content_kind','availability_scope','execution_context','viewer_modes'])||v.schema_version!=='quest-human-route/1'||v.quest_episode_id!==episode||v.content_kind!=='quest_human'||!['staff','public'].includes(v.availability_scope)||!['staff_simulation','public_real'].includes(v.execution_context)||v.availability_scope==='staff'&&v.execution_context!=='staff_simulation'||!Array.isArray(v.viewer_modes)||!['["master"]','["participant"]','["master","participant"]'].includes(JSON.stringify(v.viewer_modes)))fail('Percorso della quest non confermato dal server.');return copy(v);}

// Ordinary authoring adoption: a child of the existing connected Admin workspace.
export function mountHumanOrdinaryAdmin(root,{client,api,identity,isCurrent=()=>true,readEditor,readNpcTemplate,storage=globalThis.localStorage}={}){
 if(!root?.isConnected||typeof readEditor!=='function'||typeof readNpcTemplate!=='function')fail('Editor non collegato.');
 const actor=identity(),section=node('section');section.className='mission-factory-editor';section.setAttribute('aria-label','Quest con Master');root.append(section);
 let disposed=false,epoch=0,busy=false,source=null,roster=null,factory=null,workspace=null,preview=null,message='',planned=null;
 const alive=()=>!disposed&&section.isConnected&&isCurrent()&&identity()===actor;
 const t=normalTransport({client,identity,isCurrent:alive});
 function state(){const e=readEditor();if(!e||!UUID.test(e.draft_id)||!positive(e.control_version)||e.dirty||e.pending)fail('Salva la bozza Native e completa le richieste conservate prima di proseguire.');return e;}
 function stable(token,id,cv){if(!alive()||token!==epoch||readEditor()?.draft_id!==id||readEditor()?.control_version!==cv)fail('Bozza cambiata: nessuna scelta aggiunta alla nuova bozza.');}
 function data(){return factory?.journal().draft||{tone:'',guardrails:'',continuity:'',selected:[],planned:null};}
 function save(v){factory.setDraft(v);}
 function latest(){return factory?.journal().history.filter(x=>['create','import'].includes(x.operation)).at(-1)?.receipt||null;}
 function sourceShape(v){return exact(v,['schema_version','content_kind','catalog_version','npc_bindings','budget_policy_id','variants','quest'])&&v.schema_version==='mission-factory-draft/2'&&v.content_kind==='quest_ai'&&Array.isArray(v.npc_bindings)&&Array.isArray(v.quest?.episodes)&&exact(v.variants,['ai']);}
 async function work(fn){if(busy)return;busy=true;draw();try{await fn();message='Stato aggiornato.';}catch(e){message=userMessage(e);}finally{busy=false;if(alive())draw();}}
 async function load(){const e=state(),token=++epoch;const v=await api.openDraft({draft_id:e.draft_id,content_kind:'quest_ai'});stable(token,e.draft_id,e.control_version);if(v.draft_id!==e.draft_id||v.control_version!==e.control_version||!sourceShape(v.document))fail('Fonte Native non compatibile.');const r=await api.rosterCatalog({draft_id:e.draft_id});stable(token,e.draft_id,e.control_version);if(!exact(r,['schema_version','draft_id','eligible','assignment'])||r.schema_version!=='mission-factory-quest-roster-catalog/1'||r.draft_id!==e.draft_id||!Array.isArray(r.eligible)||r.eligible.some(x=>!exact(x,['character_id','display_name','village_scope'])||!UUID.test(x.character_id)||typeof x.display_name!=='string'||typeof x.village_scope!=='string'))fail('Partecipanti non compatibili.');
 if(workspace!==e.draft_id){factory?.dispose();workspace=e.draft_id;factory=createHumanOrdinaryAuthoring({client,identity,isCurrent:()=>alive()&&readEditor()?.draft_id===workspace,workspace,storage});if(factory.journal().draft===null){let old=null;try{old=JSON.parse(storage.getItem(`tus:quest-human-authoring:${actor}:${workspace}`)||'null');}catch{fail('Registro precedente non leggibile: nessun invio.');}if(old&&(old.schema_version!=='quest-dual-human-authoring-ui/1'||old.native_draft_id!==workspace||old.pending_import||old.pending_publish))fail('Completa il recupero della richiesta precedente prima della nuova conduzione.');save({tone:typeof old?.tone==='string'?old.tone:'',guardrails:typeof old?.guardrails==='string'?old.guardrails:'',continuity:typeof old?.continuity==='string'?old.continuity:'',selected:Array.isArray(old?.selected)?old.selected:[],planned:null});}}
 source={draft_id:v.draft_id,control_version:v.control_version,document:copy(v.document)};roster=r;let d=data();if(r.assignment){if(!Array.isArray(r.assignment.member_character_ids)||r.assignment.member_character_ids.some(id=>!r.eligible.some(x=>x.character_id===id)))fail('Gruppo Native non compatibile.');d.selected=copy(r.assignment.member_character_ids);}else d.selected=d.selected.filter(id=>r.eligible.some(x=>x.character_id===id));save(d);planned=d.planned;preview=null;
 }
 function variant(){const d=data(),q=source.document.quest;if(!d.tone.trim()||!d.guardrails.trim()||!d.continuity.trim())fail('Completa tono, indicazioni riservate e continuità.');return{state:'complete',mode:'human',document:{schema_version:'quest-creation-document/1',direction_mode:'human',quest_kind:q.quest_kind,arc_plan:{episode_order:q.episodes.map(e=>e.episode_key),continuity_notes:d.continuity.trim(),inter_episode_policy_key:null},episodes:q.episodes.map(e=>({episode_key:e.episode_key,phase_keys:e.phases.map(p=>p.step_key)})),editorial:{public_tone:d.tone.trim(),private_guardrails:d.guardrails.trim()},arenas:q.episodes.flatMap(e=>e.maps.filter(m=>m.arena_ref).map(m=>({episode_key:e.episode_key,step_key:m.step_key,template_key:m.arena_ref.template_key,template_version:m.arena_ref.template_version,zone_key:m.arena_ref.zone_key})))}};}
 function prepare(operation){const e=state();if(e.draft_id!==source?.draft_id||e.control_version!==source?.control_version)fail('Rileggi la fonte Native salvata.');if(factory.journal().pending)fail('Rileggi prima la richiesta conservata.');const d=data(),h=variant(),last=latest(),common={p_lineage:last?.lineage_id||crypto.randomUUID(),p_expected_version:last?.version||0,p_roster:copy(d.selected),p_request:crypto.randomUUID()};if(common.p_roster.length<1||common.p_roster.length>4)fail('Scegli da uno a quattro partecipanti.');let params;if(operation==='import')params={p_native_draft:source.draft_id,p_native_version:source.control_version,p_human_variant:h,...common};else{const doc=copy(source.document);doc.schema_version='mission-factory-draft/3';doc.content_kind='quest_dual';doc.variants.human=h;doc.quest.roster_assignment_id=null;params={...common,p_document:doc};}authorParams(operation,params);planned={operation,params,native_draft_id:source.draft_id,native_version:source.control_version};d.planned=copy(planned);save(d);}
 async function sendPlanned(){const e=state(),p=data().planned;if(!p||e.draft_id!==p.native_draft_id||e.control_version!==p.native_version)fail('Prepara la richiesta sulla fonte Native attuale.');await factory.send(p.operation,p.params);const d=data();d.planned=null;save(d);planned=null;preview=null;}
 async function canonical(binding){const e=state(),token=epoch;const detail=await readNpcTemplate(binding.npc_id);stable(token,e.draft_id,e.control_version);const template=detail?.template||detail;if(template.id!==binding.npc_id||!positive(template.control_version)||!UUID.test(template.current_version_id))fail('Rileggi il profilo approvato del PNG.');await factory.send('canonical',{p_template:template.id,p_narrative_version:template.current_version_id,p_expected_template_control:template.control_version,p_request:crypto.randomUUID()});}
 function draw(){if(!alive())return;section.replaceChildren();notice(section,busy,message);section.append(node('h3','Quest con Master'),action('Leggi la bozza Native salvata',()=>work(load),busy));if(!source||workspace!==readEditor()?.draft_id)return;const d=data(),j=factory.journal();if(j.pending){section.append(node('p','La richiesta originale è conservata.'),action('Rileggi la stessa richiesta',()=>work(()=>factory.recover()),busy),action('Ripeti la stessa richiesta',()=>work(()=>factory.replay()),busy));return;}
 for(const [key,label] of [['tone','Tono del racconto'],['guardrails','Indicazioni riservate'],['continuity','Continuità fra le puntate']]){const l=node('label',label),input=node('textarea');input.value=d[key];input.disabled=busy;input.addEventListener('input',()=>{const next=data();next[key]=input.value;next.planned=null;save(next);planned=null;});l.append(input);section.append(l);}
 const group=node('fieldset');group.append(node('legend','Partecipanti'));for(const p of roster.eligible){const l=node('label',p.display_name),c=node('input');c.type='checkbox';c.checked=d.selected.includes(p.character_id);c.disabled=busy||!!roster.assignment;c.addEventListener('change',()=>{const next=data();next.selected=c.checked?[...new Set([...next.selected,p.character_id])]:next.selected.filter(x=>x!==p.character_id);next.planned=null;save(next);planned=null;});l.prepend(c);group.append(l);}section.append(group);
 section.append(action('Prepara importazione',()=>work(()=>prepare('import')),busy),action('Prepara nuova versione',()=>work(()=>prepare('create')),busy));if(d.planned){const audit=node('details');audit.append(node('summary','Dettagli Staff della richiesta preparata'),node('pre',JSON.stringify(d.planned,null,2)));section.append(node('p','Richiesta preparata e conservata. Il server verifica la disponibilità prima di salvarla.'),audit,action('Conferma il salvataggio preparato',()=>work(sendPlanned),busy));}
 for(const b of source.document.npc_bindings){if(!UUID.test(b.npc_id))continue;section.append(action(`Certifica profilo Combat: ${b.actor_key||'PNG'}`,()=>work(()=>canonical(b)),busy));}
 const r=latest();if(r){section.append(action('Anteprima',()=>work(async()=>{preview=await factory.preview(r.draft_id,r.version);}),busy));if(preview){section.append(node('p',preview.errors.length?'Correggi la bozza prima della pubblicazione.':'Anteprima convalidata dal server.'));if(preview.preview_seal)section.append(action('Pubblica la quest',()=>work(async()=>{await factory.send('publish',{p_draft:r.draft_id,p_expected_version:r.version,p_preview_seal:preview.preview_seal,p_request:crypto.randomUUID(),p_visibility:'open',p_scheduled_at:null});}),busy));}const pub=j.history.filter(x=>x.operation==='publish'&&x.receipt.draft_id===r.draft_id).at(-1)?.receipt;if(pub){const a=node('a','Apri la quest in LAND');a.href=`land.html?quest_human_episode=${encodeURIComponent(pub.quest_episode_id)}`;section.append(a);}}
 }
 draw();return{read:()=>work(load),dispose(){disposed=true;epoch++;factory?.dispose();t.dispose();section.hidden=true;}};
}
